-- food menu snapshots, batch 7 (25 menus)
with target as (
  select slug from venues where slug = 'ngajeng-restaurant' and status = 'active' and publication_status = 'published'
), m as (
  insert into menus (venue_slug, title, version, status, completeness, source_url, source_label,
                     captured_at, verified_at, expires_at, content_digest, kind)
  select t.slug, 'Ngajeng Restaurant Menu', 1, 'draft', 'partial', 'https://ngajengrestaurant.com/menu', 'Official Ngajeng Restaurant menu',
         '2026-08-25T01:47:06+00:00'::timestamptz, null, '2026-11-23T01:47:06+00:00'::timestamptz, 'b2f963e0461c5f885ea93555c98b182ac62b5c14b9da377a323d8e43cf520e4b', 'food'
  from target t
  where not exists (select 1 from menus x, target t2 where x.venue_slug = t2.slug and x.kind = 'food')
  returning id
), secs as (
  insert into menu_sections (menu_id, name, position)
  select m.id, s.name, s.pos from m, (values ('BITES TO SHARE', 0), ('SALADS & BOWLS', 1), ('SOUPS', 2), ('MAIN COURSE', 3), ('SANDWICHES', 4), ('BURGERS', 5), ('PASTA', 6), ('HOUSE OF PIZZA', 7), ('INDONESIAN VOYAGE', 8), ('DESSERT', 9)) as s(name, pos)
  returning id, name
)
