insert into menu_items (menu_id, section_id, name, description, price_minor, currency, position)
select m.id, secs.id, i.name, i.descr, i.price, i.cur, i.pos
from m, secs
join (values ('Spa Treatments', 'Aloe Vera Body Scrub & Mask', 'Aloe Vera is known for its natural moisturizing and healing properties. It can help heal damage left from skin blemishes, and clear blackheads, especially when used in combination with a light, exfoliating scrub. The gentle scrub removes oils from the surface of the skin, as well as dead skin cells which might clog pores and create impurities and blemishes. The Aloe Vera Scrub Bath includes a 60 m', 615000, 'IDR', 0), ('Spa Treatments', 'Aloe Vera Sunburn Treatment', 'Due to its natural cooling properties, aloe vera is a great product for soothing sunburns. It is anti-inflammatory in nature with mineral and antioxidant content that accelerates the process of healing. If you have a stinging sunburn, apply a generous dose of aloe vera gel and it will calm the skin. Aloe Deeply Hydrating, Skin, Nourishing After Sun Skin Care for whole body such as sunburn, Redness', 300000, 'IDR', 1), ('Spa Treatments', 'Chocolate Body Scrub', 'Enjoy a traditional Balinese Massage, a wrap is a wrap, but a chocolate wrap is extra especially luxurious. The smell of chocolate is not too potent but is just enough to make you feel warm, snug, and happy. Many of these treatments feature nurturing warmed chocolate. Your chocolate body treatment and chocolate body wrap using 100% pure cocoa butter and essential oils, this body scrub and massage ', 615000, 'IDR', 2), ('Spa Treatments', 'Citrus Bath', 'The citric acid and vitamin C in the citrus peels help to shrink pores, revive your skin, promote circulation, and reduce sensitivity to cold – these health benefits make citrus bath an extremely popular winter bath. This treatment will also help to shine up your skin and scalp while pulling stored toxins from your body. Rejuvenating essences of lemon, orange, and orange leaves will escalate the s', 450000, 'IDR', 3), ('Spa Treatments', 'Clay Body Scrub', 'Enjoying a traditional Balinese Massage, clay body scrub and clay body mask that will produce the best results is an important, and even crucial part of the entire treatment. It will allow you to achieve your goal whether it’s losing inches, detoxifying, having that radiant, younger-looking, softer skin, or all the above. Finally, enjoy relaxing with flower bath, and Body Moisturizer.', 615000, 'IDR', 4), ('Spa Treatments', 'Coconut Body Scrub', 'Our Coconut Exfoliating Cream Body Scrub feels just like a trip to a tropical paradise. It’s refreshing, relaxing and smells wonderfully coconutty. Just scrub up with this coconut exfoliator and you’ll have holiday skin that feels softer and smoother without ever leaving home.', 615000, 'IDR', 5), ('Spa Treatments', 'Coffee Body Scrub', 'Enjoy a traditional Balinese Massage, and the Surprising Skin Care Benefits of Scrubs coffee Great for sensitive skin. This makes it an excellent skin care ingredient to use in bath designed to be gentle on sunburned skin, winter-reddened skin, or other skin sensitivities.', 615000, 'IDR', 6), ('Spa Treatments', 'Green Tea Body Scrub', 'Enjoy a traditional for one hour with aroma therapy oil then followed by natural green tea body scrub then refresh with yoghurt. Finally immerse yourself in a bath of delicate scented flowers.', 615000, 'IDR', 7), ('Spa Treatments', 'Milk Bath Body Scrub', 'Enjoy a traditional massage for one hour with aroma therapy oil, then followed by our soothing Milk Body Scrub.', 615000, 'IDR', 8), ('Spa Treatments', 'Ratus Treatment', 'The Ratus feminine hygiene treatment is a traditional Indonesian treatment created for Javanese princesses, to freshen and improve the health of a woman’s intimate area. It will improve blood circulation and relax the pelvic floor muscles to help maintain their elasticity.', 300000, 'IDR', 9), ('Spa Treatments', 'Sea Salt Body Scrub', 'Enjoy a traditional massage for one hour with aroma therapy oil, then followed by using our Sea Salt Body Scrub and essential oil. This treatment removes dead skin and is especially good for sensitive skin.', 615000, 'IDR', 10), ('Spa Treatments', 'Sensation of Javanese Lulur', 'Enjoy a traditional for one hour with aroma therapy oil then followed by a turmeric/Javanese lulur scrub to exfoliate your skin. Yoghurt is gently applied to the skin.', 615000, 'IDR', 11), ('Spa Treatments', 'Spice Bath', 'Enjoy a traditional Balinese massage for one hour with Aroma oil, then followed by natural spice body scrub and at last we will indulge you with a wonderful relaxing warm bath experience and body moisturizer.', 615000, 'IDR', 12), ('Spa Treatments', 'Traditional Balinese Body Mask (Boreh)', 'Enjoy a traditional massage using Spice Oil, followed by a Balinese Boreh Body Mask, highly recommended if you have a fever, headaches, muscles aches and arthritis.', 430000, 'IDR', 13), ('Spa Treatments', 'V Steam Treatment', '“V” FRESH v stream Designed ancient Asian remedy that detoxed the vaginal passage using herbs-infused steam to ease menstrual cramps, balance out hormones and pH balance.', 350000, 'IDR', 14)) as i(sec, name, descr, price, cur, pos) on i.sec = secs.name;

