select m.id, secs.id, i.name, i.descr, i.price, i.cur, i.pos
from m, secs
join (values ('Massages', 'Balinese', 'A deep full-body massage using ancient Balinese therapeutic techniques. Stretching, rolling and pressure gently release tension, induce calm and elevate the spirit. Select from four massage oil blends: Ayung Cocoon: lavender, vetiver, bergamot; Breath of Bali: frankincense, ylang-ylang, sandalwood; Morning Mantra: cajeput, ginger, lavender; Pure Refinement: virgin coconut oil.', 2800000, 'IDR', 0), ('Massages', 'Warm Riverstone', 'Release tension and restore calm with steam heated stones from the Ayung River. Smoothed over centuries, they combine with aromatic oils to balance the muscles and stimulate the energy centers.', 3200000, 'IDR', 1), ('Massages', 'Deep Knead', 'Release inner tension with this deep massage treatment. Healing therapeutic techniques increase flexibility, relieve tightness and enhance circulation for full-body relaxation.', 2800000, 'IDR', 2), ('Massages', 'Extreme Ease', 'A soothing therapy to restore equilibrium. A relaxing head, neck and shoulder massage is followed by reflexology for the feet and hands, enhancing blood flow and bringing a sense of pure ease.', 2800000, 'IDR', 3), ('Massages', 'Complete Body Alignment', 'Performed fully clothed, this osteopathy-inspired treatment restores inner balance. Stretches, manipulations and joint articulations promote complete alignment, restoring the body’s natural self-healing flow.', 3400000, 'IDR', 4), ('Massages', 'Aromatherapeutic Relax', 'A journey of pure renewal with therapeutic Synthesis Organics oil blends. Surrender to stillness with an inhalation ritual, a restorative full-body massage, and a pulse-point activation.', 2800000, 'IDR', 5), ('Massages', 'Mother-To-Be', 'A nourishing, calming and restorative treatment. A lavender and rose herb poultice massage replenishes dry skin and relieves discomfort. An optional body scrub and polish adds lustre. This treatment is available after 13 weeks’ gestation.', 3200000, 'IDR', 6), ('Massages', 'Cancer Care', 'A nurturing treatment to bring balance at every stage. Bespoke oils and expert therapeutic techniques soothe irritated skin and scar tissue, and provide lymph support, helping to alleviate anxiety and lift spirits.', 2800000, 'IDR', 7)) as i(sec, name, descr, price, cur, pos) on i.sec = secs.name;

