join (values ('Massage Treatments', 'Aromatherapy Massage', 'Experience the calming power of an Aromatherapy Massage, where therapeutic essential oils are blended with expert massage techniques to relax the body and soothe the mind. Essential oils are gently and rhythmically stroked along the body to relax and reinvigorate. Reception will help you choose just the right blend.', 650000, 'IDR', 0), ('Massage Treatments', 'Ayurvedic Massage', null, 750000, 'IDR', 1), ('Massage Treatments', 'Esalen™', 'Immerse yourself in the deeply soothing rhythms of a 90-minute Esalen™ Massage, a unique and transformative bodywork experience rooted in the healing traditions of California’s Esalen Institute. This massage features long, flowing strokes, gentle rocking, and intuitive touch, creating a seamless and nurturing connection throughout the session. This massage invites you to unwind, release tension, a', 700000, 'IDR', 2), ('Massage Treatments', 'Lomi Lomi 60 Minutes', 'Embark on a deeply relaxing journey with our Lomi Lomi Massage, a Hawaiian-inspired treatment designed to harmonize your body, mind, and spirit. Performed using long, flowing, wave-like strokes with the forearms and hands, this massage mimics the soothing rhythm of the ocean, promoting a sense of balance and renewal.', 450000, 'IDR', 3), ('Massage Treatments', 'Lomi Lomi 90 Minutes', 'Embark on a deeply relaxing journey with our Lomi Lomi Massage, a Hawaiian-inspired treatment designed to harmonize your body, mind, and spirit. Performed using long, flowing, wave-like strokes with the forearms and hands, this massage mimics the soothing rhythm of the ocean, promoting a sense of balance and renewal.', 600000, 'IDR', 4), ('Massage Treatments', 'Lymphatic', 'Experience the revitalizing benefits of our 90-minute Lymphatic Massage, a detoxifying treatment designed to stimulate your body’s natural drainage system and promote overall wellness. Using gentle, rhythmic strokes and light pressure, this massage targets key lymph nodes to enhance circulation, reduce fluid retention, and improve the body’s ability to eliminate toxins.', 650000, 'IDR', 5), ('Massage Treatments', 'Myofascial Release', 'Discover the transformative effects of Myofascial Release, a therapeutic treatment designed to release tension, restore flexibility, and promote deep relaxation. This technique targets the fascia—the connective tissue surrounding muscles and organs—by applying gentle, sustained pressure to specific areas of tightness or restriction. As the fascia is released, tension melts away, allowing the body ', 650000, 'IDR', 6), ('Massage Treatments', 'Premium Balinese 60 Minutes', 'Enhance your Balinese Massage with a choice of three blends of Taksu exclusive oils: - Sacred Woods this blend is for spiritual calming. It has antibacterial, antioxidant, immune stimulant and dermal astringent properties. Synergy of 8 Essential Oils: Cypress, Cedarwood, Sandalwood, Juniper/Juniper berry, Atlas Cedarwood, Amber, Vetiver.', 650000, 'IDR', 7), ('Massage Treatments', 'Premium Balinese 90 Minutes', 'Enhance your Balinese Massage with a choice of three blends of Taksu exclusive oils: - Sacred Woods this blend is for spiritual calming. It has antibacterial, antioxidant, immune stimulant and dermal astringent properties. Synergy of 8 Essential Oils: Cypress, Cedarwood, Sandalwood, Juniper/Juniper berry, Atlas Cedarwood, Amber, Vetiver.', 750000, 'IDR', 8), ('Massage Treatments', 'Pulse Point Balancing 1 Therapist', 'Experience the rejuvenating power of Pulse Point Balancing, a full-body massage that restores harmony and balance to your body’s energy. Through targeted pressure on key pulse points, this therapeutic massage helps release tension, improve circulation, and promote deep relaxation, leaving you feeling revitalized and centered.', 550000, 'IDR', 9), ('Massage Treatments', 'Pulse Point Balancing 2 Therapist', 'Experience the rejuvenating power of Pulse Point Balancing, a full-body massage that restores harmony and balance to your body’s energy. Through targeted pressure on key pulse points, this therapeutic massage helps release tension, improve circulation, and promote deep relaxation, leaving you feeling revitalized and centered.', 680000, 'IDR', 10), ('Massage Treatments', 'Thai Massage', null, 700000, 'IDR', 11), ('Massage Treatments', 'The Soother', 'Take a break from stress with The Soother, a 45-minute dry massage designed to target your back, head, neck, and shoulders. This treatment is perfect for those on the go, as it’s performed with clothes on, offering an invigorating yet soothing experience. Using gentle pressure and expert techniques, the therapist releases tension and alleviates tightness in key areas where stress often builds up. ', 340000, 'IDR', 12), ('Massage Treatments', 'Traditional Balinese 60 Minutes', 'Experience the essence of Balinese culture with this 60-minute traditional massage that blends ancient techniques with modern relaxation. Using long, gentle strokes, kneading, and acupressure, the therapist skillfully relieves tension and improves circulation. Warm aromatic oils infused with local herbs enhance the experience, leaving your skin soft and your mind refreshed. Perfect for guests seek', 500000, 'IDR', 13), ('Massage Treatments', 'Traditional Balinese 90 Minutes', 'Experience the essence of Balinese culture with this 60-minute traditional massage that blends ancient techniques with modern relaxation. Using long, gentle strokes, kneading, and acupressure, the therapist skillfully relieves tension and improves circulation. Warm aromatic oils infused with local herbs enhance the experience, leaving your skin soft and your mind refreshed. Perfect for guests seek', 650000, 'IDR', 14), ('Massage Treatments', 'Warm Stone', 'Immerse yourself in the deeply soothing rhythms of a 90-minute Esalen™ Massage, a unique and transformative bodywork experience rooted in the healing traditions of California’s Esalen Institute. This massage features long, flowing strokes, gentle rocking, and intuitive touch, creating a seamless and nurturing connection throughout the session. This massage invites you to unwind, release tension, a', 650000, 'IDR', 15)) as i(sec, name, descr, price, cur, pos) on i.sec = secs.name;

